    `name` VARCHAR(35) CHARACTER SET utf8 NOT NULL,
    `sex` TINYINT(1) DEFAULT NULL,
    CONSTRAINT `pk_altrec_names` PRIMARY KEY (`name`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

